import {destinationQuest} from './destination-quests.mjs?v=32';
import {PASSENGERS,passengerFor,passengerPortrait,storyFor,rideStatus,RIDE_RULES} from './passengers.mjs?v=32';
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=value=>Math.floor(Number(value)||0).toLocaleString();
const timeLeft=value=>{const n=Math.max(0,Math.ceil(value||0));return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');};
const paths={people:'M8 11a4 4 0 110-8 4 4 0 010 8 M1 22v-3a7 7 0 0114 0v3 M17 4a3 3 0 010 6 M18 14a5 5 0 015 5v3',phone:'M7 2h10v20H7z M10 18h4',quests:'M8 5H5v17h14V5h-3 M9 2h6v6H9z M8 12l2 2 5-4 M8 18h8',dispatch:'M4 10a8 8 0 0116 0v6 M4 10H2v7h4v-7 M20 10h2v7h-4v-7 M18 18v3h-6',map:'M2 5l7-3 6 3 7-3v17l-7 3-6-3-7 3z M9 2v17 M15 5v17',garage:'M3 15l2-8h14l2 8 M3 12h18v7H3z M5 19v3 M19 19v3 M6 15h2 M16 15h2',apartment:'M2 11L12 2l10 9 M5 9v13h14V9 M10 22v-8h5v8',stats:'M3 21h18 M5 18v-5h3v5 M11 18V8h3v10 M17 18V3h3v15',settings:'M4 5h16 M4 12h16 M4 19h16 M8 2v6 M16 9v6 M10 16v6',guide:'M3 3h7l2 2 2-2h7v17h-7l-2 2-2-2H3z M12 5v17',back:'M15 5l-7 7 7 7',close:'M5 5l14 14 M19 5L5 19',home:'M2 11L12 2l10 9 M5 10v12h14V10',arrow:'M4 12h16 M14 6l6 6-6 6'};
const APP_ART=new Set(['quests','dispatch','map','garage','apartment','stats','settings','guide','people']);
export const phoneIcon=(name='phone')=>APP_ART.has(name)?`<img class="phone-app-art" src="/assets/phone-apps/${name}.png" alt="" aria-hidden="true" width="72" height="72" draggable="false">`:`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="square" stroke-linejoin="miter" aria-hidden="true">${name==='close'?`<path d="${paths.close}"/>`:`<path d="${paths[name]||paths.phone}"/>`}</svg>`;
const APPS=[['quests','Quests','mint'],['dispatch','Dispatch','amber'],['map','City map','blue'],['garage','Garage','purple'],['apartment','Home','peach'],['stats','My stats','mint'],['settings','Settings','slate'],['guide','Guide','blue'],['people','People','peach']];
const FIRST_STEPS=['Explore your apartment','Read the laptop briefing','Head downstairs','Pick up your first passenger','Complete the delivery','Bank your haul at Last Exit'];
export function phoneQuests(s){const p=s.profile,live=s.shift,home=s.homeLife?.completed||[],fares=p.deliveries+(live?.deliveries||0);return[
 {id:'first-night',name:'Your first night',detail:'Learn the job, deliver your first fare, and bank the haul.',value:p.tutorialStep,total:6,unit:'steps',next:FIRST_STEPS[p.tutorialStep]||'First shift complete',main:true},
 {id:'ten-fares',name:'A familiar face',detail:'Complete ten passenger deliveries.',value:fares,total:10,unit:'deliveries',next:'Pick up and deliver passengers'},
 {id:'big-bank',name:'A night to remember',detail:'Bank 5,000 credits in a single shift.',value:p.best,total:5000,unit:'best haul',next:'Build a haul, then return to Last Exit'},
 {id:'five-shifts',name:'Night regular',detail:'Finish five shifts in the city.',value:p.runs,total:5,unit:'shifts',next:'Finish another shift'},
 {id:'home-comforts',name:'Make yourself at home',detail:'Make coffee, watch TV from the sofa, shower, and rest.',value:home.length,total:4,unit:'activities',next:'Try something new at home'}
 ].map(q=>({...q,value:Math.min(q.total,q.value),complete:q.value>=q.total,tracked:p.trackedQuest===q.id}));}

export function createGamePhone(api){
 let active=false,page='home',message='',personId=PASSENGERS[0].id,detailReturn='people';const $=id=>document.getElementById(id),s=()=>api.state();
 const guard=fn=>(...args)=>{if(!api.busy())return fn(...args);};
 function open(next='home'){if(api.busy())return;api.navigate?.();active=true;page=next;message='';api.pause();if(page==='garage'){api.garage();return;}render();}
 function frame(content){const state=s(),title=page==='rider'?'Passenger profile':page==='home'?'GETAWAY OS':APPS.find(a=>a[0]===page)?.[1]||'Garage';return `<div class="game-phone"><div class="phone-status"><span>${escape(state.clock)}</span><span class="phone-speaker" aria-hidden="true"></span><span>${state.online?'NEIGHBORHOOD ONLINE':'SOLO PLAY'}</span></div><header class="phone-header"><button id="phoneBack" aria-label="Back to phone home">${phoneIcon('back')}</button><h2 id="phoneTitle">${page!=='home'?phoneIcon(page==='rider'?'people':page):''}<span>${escape(title)}</span></h2><button id="phoneClose" aria-label="Put phone away">${phoneIcon('close')}</button></header><div class="phone-pause-note">${state.mode==='driving'?'SHIFT PAUSED · '+timeLeft(state.shift?.time)+' LEFT':'AT HOME · NO TIMER'}</div><main class="phone-screen" id="phoneScreen" tabindex="-1">${content}</main><nav class="phone-nav" aria-label="Phone navigation"><button data-phone-app="quests" aria-label="Quests">${phoneIcon('quests')}<span>Quests</span></button><button data-phone-app="home" class="phone-home-key" aria-label="Phone home">${phoneIcon('home')}</button><button data-phone-app="map" aria-label="City map">${phoneIcon('map')}<span>Map</span></button></nav></div>`;}
 function bindFrame(){const root=$('modalRoot');$('phoneClose').onclick=guard(api.close);$('phoneBack').onclick=guard(()=>page==='rider'?open(detailReturn):page==='home'?api.close():open('home'));root.querySelectorAll('[data-phone-app]').forEach(b=>b.onclick=guard(()=>open(b.dataset.phoneApp)));}
 function card(label,value){return `<div><span>${label}</span><strong>${value}</strong></div>`;}
 function questBar(q){return `<progress max="${q.total}" value="${q.value}" aria-label="${escape(q.name)} progress"></progress><div class="phone-progress-label"><span>${number(q.value)} / ${number(q.total)} ${q.unit}</span><span>${q.complete?'Complete':q.tracked?'Tracking':'In progress'}</span></div>`;}
 function homePage(state){const q=phoneQuests(state).find(q=>q.tracked)||phoneQuests(state)[0];return `<div class="phone-welcome"><span>LAST EXIT / DRIVER 04</span><h3>${state.mode==='driving'?'Take a breather.':'Your night starts here.'}</h3><p>${escape(state.mode==='driving'?state.carName:state.roomName+' · Apartment 04')}</p></div><div class="phone-wallet">${card('BANKED CREDITS',number(state.profile.credits)+' <small>CR</small>')}${card(state.shift?'UNBANKED HAUL':'BEST SHIFT',number(state.shift?state.shift.haul+state.shift.style:state.profile.best)+' <small>CR</small>')}</div><div class="phone-app-grid">${APPS.map(([id,label,color])=>`<button data-phone-app="${id}"><span class="app-icon ${color}">${phoneIcon(id)}</span><span>${label}</span></button>`).join('')}</div><button class="phone-quest-preview" data-phone-app="quests"><span class="phone-kicker">${q.complete?'QUEST COMPLETE':'TRACKED QUEST'}</span><strong>${escape(q.name)}</strong><span>${escape(q.next)}</span>${questBar(q)}</button><p class="phone-footnote">${state.storageAvailable?'Progress saved on this device.':'Saving unavailable in this browser.'}</p>`;}
 function destinationCards(state){return state.passengers.map(job=>{const quest=destinationQuest(job);return `<article class="phone-quest tracked"><div class="phone-card-label">PASSENGER QUEST · ${escape(quest.type)}</div><h3>${escape(quest.title)}</h3><p>${escape(job.name)} · ${escape(quest.name)}</p><p>Open the entrance, ${escape(quest.instruction.charAt(0).toLowerCase()+quest.instruction.slice(1))} Then speak with your passenger to finish.</p><button class="phone-primary" data-phone-drop="${escape(job.id)}" ${state.mode!=='driving'?'disabled':''}>ROUTE TO QUEST</button></article>`;}).join('');}
 function questsPage(state){const quests=phoneQuests(state),done=quests.filter(q=>q.complete).length;return `<div class="phone-page-intro"><span class="phone-kicker">QUEST LOG</span><h3>${done} of ${quests.length} complete</h3><p>Find your next move. Track a quest to keep it on your HUD.</p></div>${destinationCards(state)}${quests.map(q=>`<article class="phone-quest ${q.tracked?'tracked':''} ${q.complete?'complete':''}"><div class="phone-card-label">${q.main?'FIRST SHIFT':'MILESTONE'}${q.complete?' · ✓ COMPLETE':''}</div><h3>${escape(q.name)}</h3><p>${escape(q.detail)}</p>${questBar(q)}${q.id==='first-night'?`<ol class="phone-checklist">${FIRST_STEPS.map((step,i)=>`<li class="${i<state.profile.tutorialStep?'done':i===state.profile.tutorialStep?'current':''}"><span>${i<state.profile.tutorialStep?'✓':i+1}</span>${step}</li>`).join('')}</ol>`:''}${q.complete?'':`<div class="phone-button-row"><button data-track-quest="${q.id}" ${q.tracked?'disabled':''}>${q.tracked?'Tracking':'Track quest'}</button><button class="phone-primary" data-go-quest="${q.id}">${q.id==='home-comforts'&&state.mode==='driving'?'Save & go home':'Go to objective'}</button></div>`}</article>`).join('')}<p class="phone-footnote">Your fares pay credits. These milestones track progress without extra payouts.</p>`;}
 function riderHead(person){return `<div class="phone-person-head"><img src="${passengerPortrait(person)}" alt="${escape(person.name)}"><div><span>${escape(person.role)}</span><h3>${escape(person.name)}</h3></div></div>`;}
 function tripCard(job,state,available=null){const person=passengerFor(job),story=storyFor(job),rule=rideStatus(job,state.shift?.wanted||0),history=state.profile.passengerHistory?.[person.id],base=available?available.value:Math.round(job.value*state.combo);return `<article class="phone-job phone-rider-job">${riderHead(person)}<p class="phone-rider-request">“${escape(story.request)}”</p><div class="phone-rider-meta">${available?'AT '+escape(available.name)+' · '+number(available.distance)+' m away':'ON BOARD'}<br>To ${escape(job.dest.name)}${job.heat?' · POLICE RISK':''} · ${history?.rides?history.rides+' previous rides':'First ride together'}</div><div class="phone-rider-objective"><strong>${escape(rule.name)}</strong><span>${escape(rule.text)}</span>${job.ride?`<progress max="1" value="${rule.progress}" aria-label="Ride objective"></progress>`:''}</div><div class="phone-rider-meta">${number(base)} CR fare · up to ${number(base*.2+rule.bonus)} CR in tip + goal bonus</div><div class="phone-button-row"><button data-passenger-profile="${person.id}">Their story</button>${available?`<button class="phone-primary" data-phone-job="${escape(available.id)}" ${state.mode!=='driving'||state.passengers.length>=state.seats?'disabled':''}>Set pickup route</button>`:`<button class="phone-primary" data-phone-drop="${escape(job.id)}" ${state.mode!=='driving'?'disabled':''}>Route to drop-off</button>`}</div></article>`;}
 function dispatchPage(state){return `<div class="phone-page-intro"><span class="phone-kicker">LAST EXIT DISPATCH</span><h3>${state.mode==='driving'?state.passengers.length+' / '+state.seats+' seats occupied':'Meet your next passenger'}</h3><p>Everyone has somewhere to be. Read their request before choosing a ride.</p></div>${state.mode!=='driving'?'<button class="phone-primary phone-wide" data-phone-action="downstairs">Go to my car</button>':''}${state.passengers.length?`<h4 class="phone-section-label">ON BOARD</h4>${state.passengers.map(p=>tripCard(p,state)).join('')}`:''}<h4 class="phone-section-label">WAITING FOR A RIDE</h4>${state.jobs.map(j=>tripCard(j.job,state,j)).join('')||'<div class="phone-empty">No pickups available. Finish a ride or bring your haul home.</div>'}${state.mode==='driving'&&state.passengers.length>=state.seats?'<p class="phone-footnote">Your car is full. Drop off a passenger first.</p>':''}<p class="phone-footnote">Tips reward careful driving. Goal bonuses require completing the request during a driven trip. All fares are unbanked game credits until you cash out.</p>`;}
 function peoplePage(state){const history=state.profile.passengerHistory||{},met=PASSENGERS.filter(p=>history[p.id]?.rides).length;return `<div class="phone-page-intro"><span class="phone-kicker">PEOPLE OF THE NIGHT</span><h3>${met} of 12 know your name</h3><a class="phone-action" href="/crew/" target="_blank" rel="noopener">OPEN PLAYER CREW ↗</a><p>Meet the regulars. Meet their requests to continue each story.</p></div>${PASSENGERS.map(p=>`<button class="phone-contact" data-passenger-profile="${p.id}"><img src="${passengerPortrait(p)}" alt=""><span><strong>${escape(p.name)}</strong><small>${escape(p.role)}</small><small>${history[p.id]?.rides?history[p.id].rides+' rides · best '+history[p.id].bestRating+'/5':'You have not driven them yet'}</small></span></button>`).join('')}`;}
 function personPage(state){const p=PASSENGERS.find(p=>p.id===personId)||PASSENGERS[0],history=state.profile.passengerHistory?.[p.id],rides=history?.rides||0,completed=history?.chapters||0,available=state.jobs.find(j=>j.job.personId===p.id),aboard=state.passengers.find(j=>j.personId===p.id),rule=RIDE_RULES[p.kind];return `<div class="phone-profile-hero"><img src="${passengerPortrait(p)}" alt="${escape(p.name)}"><h3>${escape(p.name)}</h3><p>${escape(p.role)} · ${rides?rides+' rides together':'Your first meeting'}</p></div><p class="phone-story-text">${escape(p.bio)}</p><div class="phone-rider-objective"><strong>${escape(rule.name)}</strong><span>${escape(rule.goal)}</span>${p.heat?'<span>This passenger brings a police pursuit.</span>':''}</div>${aboard?`<button class="phone-primary phone-wide" data-phone-drop="${escape(aboard.id)}" ${state.mode!=='driving'?'disabled':''}>Route to their drop-off</button>`:available?`<button class="phone-primary phone-wide" data-phone-job="${escape(available.id)}" ${state.mode!=='driving'||state.passengers.length>=state.seats?'disabled':''}>Set pickup route</button>`:'<p class="phone-footnote">They will call again after a short break.</p>'}<h4 class="phone-section-label">${completed} / 3 STORY CHAPTERS COMPLETE</h4>${p.chapters.map((c,i)=>`<article class="phone-story-chapter ${completed>i?'finished':''}"><span>${completed>i?'✓ COMPLETE':completed===i?'NEXT RIDE':'LATER CHAPTER'} · ${i+1} / 3</span><h4>${escape(c.title)}</h4><p>${escape(completed>i?c.after:completed===i?c.request:'Complete the earlier ride to continue their story.')}</p></article>`).join('')}<p class="phone-footnote">Complete the ride goal to advance a chapter. Passenger history saves on this device; credits still need to be banked.</p>`;}
 function person(id){if(api.busy()||!PASSENGERS.some(p=>p.id===id))return;detailReturn=page==='people'?'people':'dispatch';personId=id;open('rider');}
 function mapPage(state){return `<div class="phone-page-intro"><span class="phone-kicker">CITY NAVIGATION</span><h3>${escape(state.mode==='driving'?'Your current route':'Your car is downstairs')}</h3><p>${escape(state.mode==='driving'?state.targetName||'Choose a destination':state.profile.checkpoint?'A saved shift is waiting.':'Last Exit Garage')}</p></div><button class="phone-primary phone-wide" data-phone-action="atlas">OPEN FULL CITY ATLAS · M</button><canvas id="phoneMap" class="phone-map" width="600" height="600" role="img" aria-label="City map showing your car, pickups, drop-offs, garage, and route"></canvas><div class="phone-map-key"><span>▲ Your car</span><span>● Pickups</span><span>■ Garage</span></div>${state.mode==='driving'?`<button class="phone-primary phone-wide" data-phone-action="route-garage">Route to Last Exit</button><button class="phone-secondary phone-wide" data-phone-app="dispatch">Choose a pickup or drop-off</button>`:`<button class="phone-primary phone-wide" data-phone-action="downstairs">${state.profile.checkpoint?'Resume saved shift':'Go downstairs'}</button>`}<div class="phone-mini-stats">${card('PASSENGERS',state.passengers.length)}${card('WANTED',state.shift?Math.ceil(state.shift.wanted)+' / 5':'0 / 5')}</div>`;}
 function apartmentPage(state){return `<div class="phone-page-intro"><span class="phone-kicker">APARTMENT 04</span><h3>Make yourself at home.</h3><p>${state.mode==='driving'?'Save this shift and return home to use your apartment.':'Choose something to do. Your character walks there and uses it.'}</p></div>${state.mode==='driving'?'<button class="phone-primary phone-wide" data-phone-action="return-home">Save shift & return home</button>':''}<div class="phone-home-list">${state.homeSpots.map(h=>`<button data-phone-home="${h.id}" ${state.mode==='driving'?'disabled':''}><span>${escape(h.label)}<small>${escape(h.room)}</small></span><b>${state.homeLife.completed.includes(h.id)?'✓':'→'}</b></button>`).join('')}</div>`;}
 function statsPage(state){const p=state.profile;return `<div class="phone-page-intro"><span class="phone-kicker">DRIVER 04</span><h3>Your night, in numbers.</h3><p>${escape(state.driverName)} · ${escape(state.skinName)}</p></div><div class="phone-stat-grid">${card('BANKED',number(p.credits)+' CR')}${card('BEST SHIFT',number(p.best)+' CR')}${card('DELIVERIES',number(p.deliveries))}${card('SHIFTS FINISHED',number(p.runs))}${card('CARS UNLOCKED',p.unlocked.length+' / 6')}${card('QUESTS COMPLETE',phoneQuests(state).filter(q=>q.complete).length+' / 5')}</div><article class="phone-quest"><span class="phone-card-label">${state.shift?'CURRENT / SAVED SHIFT':'EQUIPPED RIDE'}</span><h3>${escape(state.carName)}</h3><p>${state.shift?timeLeft(state.shift.time)+' remaining · '+number(state.shift.haul+state.shift.style)+' CR unbanked':'Your selected ride is ready for the next shift.'}</p><button class="phone-secondary phone-wide" data-phone-app="garage">Open garage</button></article><p class="phone-footnote">Banked credits are arcade points. Your profile and collection save on this device.</p>`;}
 function settingsPage(state){return `<div class="phone-page-intro"><span class="phone-kicker">GAME SETTINGS</span><h3>Your setup.</h3></div><div class="phone-setting"><span>Sound<small>Music and game effects</small></span><button data-phone-action="sound">${state.profile.muted?'Off':'On'}</button></div><div class="phone-setting"><span>Camera<small>${state.mode==='driving'?'Driving perspective':'Apartment view'}</small></span><button data-phone-action="camera">${escape(state.cameraName)}</button></div><div class="phone-setting"><span>Progress<small>${state.storageAvailable?'Saved on this device':'Saving unavailable'}</small></span><button data-phone-action="save">Save now</button></div><button class="phone-secondary phone-wide" data-phone-action="fullscreen">Toggle full screen</button>${state.mode==='driving'?'<button class="phone-primary phone-wide" data-phone-action="return-home">Save shift & return home</button><button class="phone-secondary phone-wide" data-phone-action="recover">Recover car · −8 integrity</button><button class="phone-secondary phone-wide" data-phone-action="restart">Restart shift · lose unbanked haul</button>':'<button class="phone-primary phone-wide" data-phone-action="downstairs">Go downstairs</button>'}<p id="phoneMessage" class="phone-message" role="status">${escape(message)}</p>`;}
 function guidePage(){return `<div class="phone-page-intro"><span class="phone-kicker">DRIVER’S HANDBOOK</span><h3>Know the night.</h3><p>Pick up passengers, deliver them, then bank the haul at Last Exit.</p></div><div class="phone-guide"><h4>At home</h4><p>Click the floor to walk. Click furniture to use it, or choose an activity in the Home app. WASD moves; E interacts.</p><h4>On the road</h4><p>WASD drives. Space drifts. Shift boosts. Stop in pickup rings to board passengers. At their destination, open the door, complete the marked handoff, and talk to them inside. Completing the quest awards the fare and adds up to 40 seconds. Your shift pauses during visits.</p><h4>Passenger requests</h4><p>Smooth trips and intact cargo earn bonuses. Rush riders have a deadline; missing it keeps the base fare. Thrill riders want four seconds of boost. Discreet riders must lose their police tail before they can get out. Open People to follow each story.</p><h4>Keep your credits</h4><p>Return to Last Exit and press E to bank your haul. Running out of time or wrecking the car loses unbanked credits.</p><h4>Your phone</h4><p>M opens the full city atlas. P opens or closes the phone. Escape puts it away. Your shift pauses while you use it. The screen button works on phones and tablets.</p><h4>Your collection</h4><p>Use banked credits for original rides. Special cars and skins use demo burns until real token burns are enabled.</p></div><a class="phone-secondary phone-wide" href="/docs/" target="_blank" rel="noopener noreferrer">Read full game docs</a>`;}
 function render(){const state=s();const pages={home:homePage,quests:questsPage,dispatch:dispatchPage,map:mapPage,apartment:apartmentPage,stats:statsPage,settings:settingsPage,guide:guidePage,people:peoplePage,rider:personPage};api.modal((pages[page]||homePage)(state));bindFrame();const root=$('modalRoot');root.querySelectorAll('[data-passenger-profile]').forEach(b=>b.onclick=guard(()=>person(b.dataset.passengerProfile)));root.querySelectorAll('[data-track-quest]').forEach(b=>b.onclick=guard(()=>{api.track(b.dataset.trackQuest);render();}));root.querySelectorAll('[data-go-quest]').forEach(b=>b.onclick=guard(()=>api.goQuest(b.dataset.goQuest)));root.querySelectorAll('[data-phone-job]').forEach(b=>b.onclick=guard(()=>api.routeJob(b.dataset.phoneJob)));root.querySelectorAll('[data-phone-drop]').forEach(b=>b.onclick=guard(()=>api.routeDrop(b.dataset.phoneDrop)));root.querySelectorAll('[data-phone-home]').forEach(b=>b.onclick=guard(()=>api.homeActivity(b.dataset.phoneHome)));root.querySelectorAll('[data-phone-action]').forEach(b=>b.onclick=guard(async()=>{const result=await api.action(b.dataset.phoneAction);if(active&&page==='settings'){message=result||'';render();}}));if(page==='map')api.drawMap($('phoneMap').getContext('2d'),600);}
 return {open,person,frame,bindFrame,isOpen:()=>active,page:()=>page,closed(){active=false;},refresh(){if(active&&page!=='garage')render();}};
}
